[InitializeOnLoad]
public static class HolmesCpConsumer {
 const string K="HOLMES122_RUNNING", Done="HOLMES122_IMPORTED", W="HOLMES122_WORK";
 [Serializable] class Ref { public string guid,file_id; }
 [Serializable] class Group { public string topology; public int[] indices; }
 [Serializable] class Matrix { public float[] values; }
 [Serializable] class Influence {public int bone;public float weight; public int bits;}
 [Serializable] class Point {public Influence[] influences;}
 [Serializable] class Skin {public Ref mesh,renderer,root,source_root;public Ref[] bones,bone_parents,materials,source_bones,source_parents;public Vector3[] vertices,normals;public Vector2[] uv;public Group[] groups;public Matrix[] bindposes;public Point[] weights;public float[] matrix;public int shapes;public bool cloth; public string[] realization;}
 [Serializable] class Task {public string source_model_guid,model_guid,variant_path,kind;}
 [Serializable] class Manifest {public Task[] reference_rebind_tasks;}
 [Serializable] class Report {public string instruction_id="HOLMES-20261012-02",status="FAIL",error,unity_version,phase,package_sha256,finalizer_sha256;public Skin source,post_import,post_apply,variant;public bool apply,source_bytes_preserved,repeat_apply;public string[] rejection;public bool weight_proof,compatibility_proof;public string weight_error;public string[] source_components,edited_components;}
 static string Arg(string key){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,key);return i<0?"":a[i+1];}
 static string Work=>SessionState.GetString(W,Arg("-freshWork"));
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static Ref Id(UnityEngine.Object o){if(o==null)return null; if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(o,out string g,out long id))throw new Exception("MissingIdentity");return new Ref{guid=g,file_id=id.ToString(System.Globalization.CultureInfo.InvariantCulture)};}
 static float[] M(Matrix4x4 m){return Enumerable.Range(0,16).Select(i=>m[i]).ToArray();}
 static Skin Capture(GameObject root){var s=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var m=s.sharedMesh;var counts=m.GetBonesPerVertex();var weights=m.GetAllBoneWeights();int k=0;var points=new Point[counts.Length];try{for(int v=0;v<counts.Length;v++){var inf=new Influence[counts[v]];for(int j=0;j<inf.Length;j++){var q=weights[k++];inf[j]=new Influence{bone=q.boneIndex,weight=q.weight,bits=BitConverter.ToInt32(BitConverter.GetBytes(q.weight),0)};}points[v]=new Point{influences=inf};}}finally{counts.Dispose();weights.Dispose();}
 return new Skin{source_root=Id(PrefabUtility.GetCorrespondingObjectFromSource(s.rootBone)),source_bones=s.bones.Select(b=>Id(PrefabUtility.GetCorrespondingObjectFromSource(b))).ToArray(),source_parents=s.bones.Select(b=>Id(PrefabUtility.GetCorrespondingObjectFromSource(b.parent))).ToArray(),mesh=Id(m),renderer=Id(s),root=Id(s.rootBone),bones=s.bones.Select(Id).ToArray(),bone_parents=s.bones.Select(b=>Id(b.parent)).ToArray(),materials=s.sharedMaterials.Select(Id).ToArray(),vertices=m.vertices,normals=m.normals,uv=m.uv,groups=Enumerable.Range(0,m.subMeshCount).Select(i=>new Group{topology=m.GetTopology(i).ToString(),indices=m.GetIndices(i,true)}).ToArray(),bindposes=m.bindposes.Select(b=>new Matrix{values=M(b)}).ToArray(),weights=points,matrix=M(s.transform.localToWorldMatrix),shapes=m.blendShapeCount,cloth=s.GetComponent<Cloth>()!=null,realization=root.GetComponentsInChildren<Transform>(true).Select(t=>{var marker=t.GetComponents<Component>().FirstOrDefault(c=>c!=null&&c.GetType().Name=="VapbRealizationMarker");return marker==null?"":EditorJsonUtility.ToJson(marker);}).Where(x=>x!="").ToArray()}; }
 static HolmesCpConsumer(){EditorApplication.update+=Wait;AssetDatabase.importPackageCompleted+=n=>SessionState.SetBool(Done,true);CompilationPipeline.assemblyCompilationFinished+=(a,m)=>{if(m.Any(x=>x.type==CompilerMessageType.Error))SessionState.SetBool("HOLMES122_ERRORS",true);};AssemblyReloadEvents.afterAssemblyReload+=()=>SessionState.SetBool("HOLMES122_RELOAD",true);}
 public static void Run(){SessionState.SetString(W,Arg("-freshWork"));SessionState.SetBool(K,true);if(Arg("-freshPhase")=="source"){Source();return;}SessionState.SetBool(Done,false);SessionState.SetBool("HOLMES122_ERRORS",false);SessionState.SetBool("HOLMES122_RELOAD",false);AssetDatabase.ImportPackage(Arg("-freshPackage"),false);}
 static void Source(){var r=new Report{unity_version=Application.unityVersion,phase="source"};try{AssetDatabase.Refresh();var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HolmesSource/Source.fbx");var mat=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(mat,"Assets/HolmesSource/SourceMaterial.mat");var imp=(ModelImporter)AssetImporter.GetAtPath("Assets/HolmesSource/Source.fbx");imp.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"SourceMaterial"),mat);imp.SaveAndReimport();AssetDatabase.SaveAssets();model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/HolmesSource/Source.fbx");r.source=Capture(model);if(r.source.vertices.Length!=4||r.source.bones.Length!=2||r.source.groups.Sum(g=>g.indices.Length)!=6||r.source.materials.Any(x=>x==null)||r.source.shapes!=0||r.source.cloth)throw new Exception("FixtureScope");AssetDatabase.ExportPackage(new[]{"Assets/HolmesSource/Source.fbx","Assets/HolmesSource/SourceMaterial.mat"},Path.Combine(Work,"../Source.unitypackage"),ExportPackageOptions.IncludeDependencies);r.package_sha256=Hash(Path.Combine(Work,"../Source.unitypackage"));r.status="PASS";}catch(Exception e){r.error=e.Message;}Finish(r);}
 static void Wait(){if(!SessionState.GetBool(K,false)||!SessionState.GetBool(Done,false)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!SessionState.GetBool("HOLMES122_RELOAD",false))return;SessionState.SetBool(K,false);var r=new Report{unity_version=Application.unityVersion,phase=Arg("-freshPhase")};try{if(SessionState.GetBool("HOLMES122_ERRORS",false))throw new Exception("CompileErrors");const string path="Assets/VAPBExport/manifest.json";var t=JsonUtility.FromJson<Manifest>(File.ReadAllText(path)).reference_rebind_tasks.Single();if(t.kind!="RESTORE_SOURCE_MODEL_SKIN_VARIANT_V1")throw new Exception("TaskKind");string src=AssetDatabase.GUIDToAssetPath(t.source_model_guid),edit=AssetDatabase.GUIDToAssetPath(t.model_guid);r.source=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(src));r.post_import=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(edit));string[] protectedPaths={src,src+".meta"};var hashes=protectedPaths.Select(Hash).ToArray();var errors=new System.Collections.Generic.List<string>();Application.LogCallback log=(msg,stack,type)=>{if(type==LogType.Error||type==LogType.Exception)errors.Add(msg);};Application.logMessageReceived+=log;var f=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("VapbModelSkinFinalizer")).Single(x=>x!=null);r.finalizer_sha256=Hash("Assets/VAPBExport/Editor/VapbModelSkinFinalizer.cs");Proof(f,path,r);r.apply=(bool)f.GetMethod("Apply").Invoke(null,new object[]{path});Application.logMessageReceived-=log;r.rejection=errors.ToArray();r.post_apply=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(edit));r.source_bytes_preserved=hashes.SequenceEqual(protectedPaths.Select(Hash));if(r.apply){r.variant=Capture(AssetDatabase.LoadAssetAtPath<GameObject>(t.variant_path));r.repeat_apply=(bool)f.GetMethod("Apply").Invoke(null,new object[]{path});}r.package_sha256=Hash(Arg("-freshPackage"));r.status="OBSERVED";}catch(Exception e){r.error=e.ToString();}Finish(r);}
 static object Invoke(Type f,string method,params object[] args){return f.GetMethod(method,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,args);}
 static object Field(object o,string name){return o.GetType().GetField(name).GetValue(o);}
 static void Set(object o,string name,object v){o.GetType().GetField(name).SetValue(o,v);}
 static void Proof(Type f,string path,Report r){try{var manifest=Invoke(f,"ReadManifest",path);object task=((Array)Field(manifest,"reference_rebind_tasks")).GetValue(0);Invoke(f,"ValidateTask",task);Invoke(f,"ValidateWeightData",task);string sourcePath=AssetDatabase.GUIDToAssetPath((string)Field(task,"source_model_guid")),editPath=AssetDatabase.GUIDToAssetPath((string)Field(task,"model_guid"));var sourceRoot=AssetDatabase.LoadAssetAtPath<GameObject>(sourcePath);var target=sourceRoot.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();object plan=Invoke(f,"PrepareWitness",task),witness=Field(plan,"witness");Invoke(f,"RefreshEditedModel",editPath,true);string guid=(string)Field(task,"source_model_guid");string[] ids=target.bones.Select(b=>Id(b).file_id).ToArray();object source=Invoke(f,"ResolveSourceIdentity",target,target,guid,ids);var transforms=(System.Collections.IDictionary)Field(witness,"transformIds");var uidById=new System.Collections.Generic.Dictionary<long,string>();foreach(System.Collections.DictionaryEntry entry in transforms)uidById.Add((long)entry.Value,(string)entry.Key);string[] uids=ids.Select(id=>uidById[long.Parse(id)]).ToArray();Set(source,"sourceBoneUids",uids);Set(source,"rootUid",uidById[long.Parse((string)Field(source,"rootUid"))]);var bones=(System.Collections.IDictionary)Field(source,"bonesByUid");bones.Clear();for(int i=0;i<uids.Length;i++)bones.Add(uids[i],target.bones[i]);if(!bones.Contains(Field(source,"rootUid")))bones.Add(Field(source,"rootUid"),target.rootBone);object edited=Invoke(f,"ResolveEdited",task,editPath,witness,source);if(!uids.SequenceEqual((string[])Field(edited,"editedBoneUids")))throw new Exception("SourceBoneOrderMismatch");Invoke(f,"ValidateExportedWeightTransport",task,editPath,edited);r.weight_proof=true;Invoke(f,"CheckSkinCompatibility",witness,target,edited,source,false);r.compatibility_proof=true;r.source_components=sourceRoot.GetComponentsInChildren<Component>(true).Select(c=>c==null?"MISSING":c.GetType().FullName).Distinct().ToArray();r.edited_components=AssetDatabase.LoadAssetAtPath<GameObject>(editPath).GetComponentsInChildren<Component>(true).Select(c=>c==null?"MISSING":c.GetType().FullName).Distinct().ToArray();if(Work.EndsWith("B-final-unity",StringComparison.Ordinal))HolmesCpNegatives.Run(f,path,Work,task,sourceRoot,target,witness,source,edited,editPath);}catch(Exception e){while(e is TargetInvocationException&&e.InnerException!=null)e=e.InnerException;r.weight_error=e.Message;}}
 public static void ObserveWeightCopy(string asset){string work=Arg("-freshWork");if(string.IsNullOrEmpty(work)||!asset.Contains("/WeightCheck_")||!asset.EndsWith("/Model.fbx"))return;var root=AssetDatabase.LoadAssetAtPath<GameObject>(asset);if(root==null)return;var skin=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var uv=new System.Collections.Generic.List<Vector2>();skin.sharedMesh.GetUVs(1,uv);if(uv.Count==0)return;var receipts=skin.bones.Select(b=>{var c=b.GetComponents<Component>().Single(x=>x!=null&&x.GetType().Name=="VapbRealizationMarker");return (string)c.GetType().GetField("boneRealizationId").GetValue(c);}).ToArray();var record=new WeightObservation{skin=Capture(root),cp_marker=uv.ToArray(),bone_receipts=receipts,fbx_sha256=Hash(asset)};string name="weight-observation-"+Guid.NewGuid().ToString("N")+".json";File.WriteAllText(Path.Combine(work,name),JsonUtility.ToJson(record,true));}
 [Serializable] class WeightObservation{public Skin skin;public Vector2[] cp_marker;public string[] bone_receipts;public string fbx_sha256;}
 static void Finish(Report r){SessionState.SetBool(K,false);File.WriteAllText(Path.Combine(Work,"native.json"),JsonUtility.ToJson(r,true));EditorApplication.Exit(r.status=="FAIL"?1:0);}
}

public sealed class HolmesCpWeightObserver:AssetPostprocessor{static void OnPostprocessAllAssets(string[] imported,string[] deleted,string[] moved,string[] movedFrom){foreach(string p in imported)HolmesCpConsumer.ObserveWeightCopy(p);}}
